INSERT INTO attack_definitions VALUES ('AI_ATTACK', 'AI / LLM Prompt Injection & Jailbreak Attack', 'Adversarial manipulation of Large Language Model (LLM) inputs to override system instructions, bypass safety guardrails, or extract sensitive data by injecting malicious directives into prompts.', 'ai', 'AI Prompt Injection and Jailbreak attacks target applications built on Large Language Models (LLMs) such as GPT, Claude, Gemini, or open-source alternatives. Attackers craft specially designed natural-language inputs that cause the model to ignore its system-level instructions, developer-defined constraints, or safety filters. Unlike traditional injection attacks that exploit parser flaws, prompt injection exploits the fundamental inability of current LLMs to reliably distinguish between trusted instructions and untrusted user-supplied data within the same context window.
INSERT INTO attack_definitions VALUES ('API_ABUSE', 'API Abuse and Exploitation', 'API Abuse encompasses attacks that exploit weaknesses in Application Programming Interface implementations, authentication mechanisms, and business logic to gain unauthorized access, exfiltrate data, or disrupt services. Common vectors include JWT token manipulation, rate limit bypasses, and parameter tampering.', 'web', 'API Abuse refers to a broad class of attacks targeting the interfaces that expose application functionality and data to clients, third parties, and internal services. Unlike traditional web vulnerabilities that target rendered HTML, API attacks exploit the programmatic contracts that define how services communicate — often leveraging weaknesses in authentication tokens, authorization logic, input validation, and rate limiting controls.
INSERT INTO attack_definitions VALUES ('AUTH_ATTACK', 'Authentication Attack', 'Authentication attacks encompass a broad class of techniques designed to bypass, subvert, or exploit weaknesses in authentication and session management mechanisms to gain unauthorized access to systems or user accounts. These include credential stuffing, session hijacking, OAuth abuse, and password reset vulnerabilities.', 'auth', 'Authentication attacks target the mechanisms that verify user identity, covering a wide spectrum from brute-force credential attacks to sophisticated session and token manipulation. Modern web applications rely on complex authentication flows — including OAuth 2.0, OpenID Connect, form-based logins, and API tokens — each presenting unique attack surfaces that adversaries actively probe and exploit.
INSERT INTO attack_definitions VALUES ('CLOUD_ATTACK', 'Cloud Infrastructure Attack', 'Cloud infrastructure attacks exploit misconfigurations, metadata services, IAM weaknesses, and SSRF vulnerabilities to gain unauthorized access to cloud resources, credentials, and sensitive data stored in platforms such as AWS, Azure, and GCP.', 'cloud', 'Cloud infrastructure attacks encompass a broad class of techniques targeting the unique attack surface presented by public cloud environments. Unlike traditional on-premises attacks, cloud-specific attacks frequently exploit the Instance Metadata Service (IMDS), Identity and Access Management (IAM) misconfigurations, overly permissive storage buckets, and lateral movement through cloud-native APIs. The IMDS endpoint (http://169.254.169.254) is an internal HTTP service available to EC2 instances and other compute resources that exposes sensitive configuration data, including temporary IAM credentials, user-data scripts, and network configuration — all without authentication in IMDSv1.
INSERT INTO attack_definitions VALUES ('CREDENTIAL', 'Credential Attack / Authentication Abuse', 'Credential attacks encompass a broad range of techniques aimed at obtaining, abusing, or bypassing authentication credentials to gain unauthorized access to systems, applications, and networks. This includes brute-force, default credential exploitation, credential stuffing, and weak authentication pattern exploitation.', 'auth', 'Credential attacks represent one of the most prevalent and consistently successful attack vectors in modern cybersecurity. Attackers leverage a variety of techniques to compromise authentication mechanisms, ranging from automated guessing of default or weak passwords to sophisticated replay attacks using stolen credential databases. These attacks exploit the fundamental trust relationship that authentication systems place in valid credentials, meaning that once an attacker possesses legitimate credentials, many downstream security controls become ineffective.
INSERT INTO attack_definitions VALUES ('CRLF', 'CRLF Injection (Carriage Return Line Feed Injection)', 'CRLF injection is an attack technique where an adversary injects Carriage Return (\r, 0x0D) and Line Feed (\n, 0x0A) characters into HTTP headers or other line-delimited protocols to manipulate response headers, split HTTP responses, or inject malicious content. This can lead to HTTP response splitting, header injection, log injection, and session fixation attacks.', 'web', 'CRLF injection exploits the fundamental structure of HTTP and other text-based protocols that use CRLF sequences as delimiters between headers and between the header section and the body. When an application fails to sanitize user-supplied input before incorporating it into HTTP response headers, an attacker can inject CRLF characters to terminate existing headers prematurely and introduce entirely new ones, or even split the HTTP response into two distinct responses.
INSERT INTO attack_definitions VALUES ('DESERIALIZE', 'Insecure Deserialization Attack', 'Insecure deserialization occurs when an application deserializes attacker-controlled data without sufficient validation, enabling remote code execution, privilege escalation, or data tampering by injecting malicious serialized objects.', 'web', 'Insecure deserialization is a class of vulnerability that arises when applications reconstruct objects from serialized data streams that originate from untrusted sources. Serialization is the process of converting in-memory objects into a transmissible byte stream or text representation (e.g., Java binary serialization, PHP serialize(), .NET BinaryFormatter, JSON, XML). Deserialization reverses this process. When an application blindly trusts and processes attacker-supplied serialized data, the attacker can manipulate the object graph to invoke unintended code paths.
INSERT INTO attack_definitions VALUES ('GRAPHQL', 'GraphQL Attack Techniques', 'GraphQL attacks exploit the flexible query language''s introspection, batching, and nesting capabilities to perform reconnaissance, denial-of-service, authorization bypass, and data exfiltration against APIs.', 'web', 'GraphQL is a query language and runtime for APIs developed by Facebook, designed to allow clients to request exactly the data they need. Unlike REST APIs, a single GraphQL endpoint accepts highly expressive queries, which introduces a unique and expansive attack surface. Attackers can leverage GraphQL''s built-in introspection system to enumerate the entire schema, discovering all types, queries, mutations, and fields without any prior knowledge of the application.
INSERT INTO attack_definitions VALUES ('IOT_ATTACK', 'IoT Device Attack (MQTT Protocol Exploitation)', 'Attacks targeting Internet of Things devices and ecosystems, with a focus on exploiting the MQTT messaging protocol through techniques such as anonymous access, weak credentials, wildcard subscriptions, command injection, and unauthorized control of industrial and consumer IoT infrastructure.', 'iot', 'IoT attacks encompass a broad range of techniques targeting the unique vulnerabilities present in embedded devices, constrained hardware, and the lightweight protocols they rely upon. The MQTT (Message Queuing Telemetry Transport) protocol, operating on TCP port 1883 (or 8883 for TLS), is a publish-subscribe messaging protocol originally designed for low-bandwidth, high-latency environments such as industrial sensors and telemetry systems. Its widespread adoption in smart home devices, industrial control systems, and connected vehicles makes it a high-value target for adversaries.
INSERT INTO attack_definitions VALUES ('K8S_ATTACK', 'Kubernetes (K8s) Attack and Exploitation', 'Kubernetes attack encompasses reconnaissance, exploitation, and lateral movement techniques targeting Kubernetes clusters, APIs, and workloads, often leveraging misconfigurations, exposed endpoints, and insecure defaults to gain unauthorized control over containerized infrastructure.', 'cloud', 'Kubernetes attack (K8S_ATTACK) refers to a broad class of adversarial activities targeting Kubernetes orchestration platforms. Kubernetes has become the dominant container orchestration system, making it a high-value target for threat actors seeking to compromise cloud-native infrastructure at scale. Attackers exploit misconfigurations, unauthenticated API endpoints, overly permissive RBAC policies, and vulnerable components to gain initial access, escalate privileges, and move laterally across workloads.
INSERT INTO attack_definitions VALUES ('LDAPI', 'LDAP Injection', 'LDAP Injection is an attack technique where malicious input is inserted into Lightweight Directory Access Protocol queries, allowing attackers to manipulate directory service operations, bypass authentication, or extract sensitive directory data.', 'auth', 'LDAP Injection is an injection-class vulnerability that occurs when user-supplied input is incorporated into LDAP queries without adequate sanitization or parameterization. LDAP (Lightweight Directory Access Protocol) is widely used for directory services such as Active Directory, OpenLDAP, and other identity management systems that store user credentials, organizational data, group memberships, and access control information. When applications construct LDAP queries dynamically using unvalidated input, attackers can inject special LDAP metacharacters and operators to alter query logic.
INSERT INTO attack_definitions VALUES ('LFI', 'Local File Inclusion (LFI)', 'Local File Inclusion is a web application vulnerability that allows an attacker to include files already present on the server through the application''s file-inclusion mechanisms, potentially exposing sensitive data or enabling code execution.', 'web', 'Local File Inclusion (LFI) is a class of web application vulnerability arising when an application dynamically includes files based on user-supplied input without adequate validation or sanitisation. Unlike Remote File Inclusion (RFI), LFI is restricted to files that already reside on the target server''s filesystem. Attackers exploit LFI by manipulating path-traversal sequences (e.g., ''../'', encoded variants, or null bytes) passed to PHP functions such as include(), require(), fopen(), or equivalent constructs in other languages.
INSERT INTO attack_definitions VALUES ('MODBUS', 'MODBUS Protocol Exploitation', 'MODBUS is a widely deployed industrial communication protocol that lacks built-in authentication or encryption, making it vulnerable to unauthorized read/write operations against PLCs, RTUs, and other OT/ICS devices. Attackers exploiting MODBUS can directly manipulate industrial processes by reading sensor data or issuing unauthorized control commands.', 'ics', 'MODBUS is a serial communication protocol developed in 1979 by Modicon (now Schneider Electric) and has become the de facto standard for industrial control system (ICS) communications. It operates over serial lines (MODBUS RTU/ASCII) or TCP/IP networks (MODBUS TCP, port 502) and is used to connect PLCs, RTUs, HMIs, sensors, and actuators across critical infrastructure sectors including energy, water treatment, manufacturing, and transportation. The protocol defines function codes that allow masters to read or write data objects on slave devices, including coils (single-bit read/write), discrete inputs (single-bit read-only), holding registers (16-bit read/write), and input registers (16-bit read-only).
INSERT INTO attack_definitions VALUES ('MODBUS_RECON', 'Modbus Protocol Reconnaissance', 'Adversaries send crafted Modbus protocol messages to enumerate connected industrial devices, discover network topology, and gather intelligence about operational technology (OT) assets prior to targeted attacks.', 'ics', 'Modbus is one of the oldest and most widely deployed industrial communication protocols, originally developed in 1979 for serial communication between programmable logic controllers (PLCs). Due to its age and design philosophy, Modbus was built with virtually no authentication, encryption, or access control mechanisms, making it inherently vulnerable to abuse by any attacker with network access to the industrial control system (ICS) segment.
INSERT INTO attack_definitions VALUES ('MQTT_ATTACK', 'MQTT Protocol Attack', 'Attacks targeting the MQTT (Message Queuing Telemetry Transport) protocol, commonly used in IoT and ICS environments, including unauthorized access via anonymous authentication, topic enumeration, wildcard subscription abuse, and scanner-based reconnaissance against MQTT brokers.', 'iot', 'MQTT (Message Queuing Telemetry Transport) is a lightweight publish-subscribe messaging protocol designed for constrained devices and low-bandwidth, high-latency networks, operating over TCP on default port 1883 (or 8883 for TLS). It is widely deployed in IoT ecosystems, industrial control systems, smart home platforms, and telemetry pipelines. Due to its lightweight design philosophy and historically weak security defaults, MQTT brokers are frequently misconfigured to allow anonymous connections, lack TLS encryption, and expose sensitive system topics.
INSERT INTO attack_definitions VALUES ('ORACLE_SCAN', 'Oracle Database Reconnaissance and TNS Listener Scanning', 'Automated scanning and enumeration of Oracle Database services via the Transparent Network Substrate (TNS) protocol to identify database versions, service names, and potential attack vectors. Attackers use tools like zgrab2 to fingerprint Oracle instances exposed on TCP/1521 and related ports.', 'recon', 'Oracle Database reconnaissance involves systematic probing of Oracle TNS Listener services to gather intelligence about exposed database infrastructure. The TNS (Transparent Network Substrate) protocol, used exclusively by Oracle Database for client-server communication, operates primarily on TCP port 1521 (and historically 1526) and exposes a wealth of information to unauthenticated requestors, including database version strings, service names, and listener status. This information is invaluable to attackers planning targeted exploitation campaigns.
INSERT INTO attack_definitions VALUES ('ORACLE_TNS', 'Oracle TNS (Transparent Network Substrate) Protocol Attack', 'Attacks targeting Oracle''s Transparent Network Substrate (TNS) protocol to enumerate database services, manipulate the Oracle Listener, and gain unauthorized access to Oracle Database infrastructure.', 'network', 'Oracle TNS (Transparent Network Substrate) is the proprietary network protocol used by Oracle Database to facilitate communication between Oracle clients and database servers. The Oracle Listener, which operates on TCP port 1521 by default, uses TNS to accept and route incoming connection requests to the appropriate database service or SID (System Identifier). TNS-based attacks exploit weaknesses in this protocol and the Listener service to conduct reconnaissance, denial-of-service, or unauthorized administrative actions against Oracle database environments.
INSERT INTO attack_definitions VALUES ('PHP', 'PHP Code Injection & Remote Code Execution', 'PHP injection attacks exploit vulnerabilities in PHP web applications to inject and execute arbitrary PHP code on the server, leveraging dangerous functions, wrapper streams, and deserialization flaws to achieve full remote code execution.', 'web', 'PHP injection represents a broad class of server-side code injection attacks targeting applications built on the PHP scripting language. Attackers exploit insufficient input validation, insecure function usage, or deserialization vulnerabilities to introduce malicious PHP code that is subsequently parsed and executed by the server''s PHP interpreter. Unlike client-side attacks, successful PHP injection gives the attacker execution context on the server itself, operating under the web server process''s user account and permissions.
INSERT INTO attack_definitions VALUES ('PROTO_ABUSE', 'Protocol Abuse and Misuse', 'Protocol abuse involves exploiting legitimate network protocols in unintended or malicious ways, leveraging design weaknesses, misconfigurations, or implementation flaws to achieve unauthorized access, data exfiltration, lateral movement, or command-and-control communications.', 'network', 'Protocol abuse (PROTO_ABUSE) encompasses a broad class of attacks where adversaries exploit the inherent design, trust assumptions, or implementation details of standard network protocols to conduct malicious activities. Unlike vulnerability exploitation targeting a specific CVE, protocol abuse often leverages intended protocol functionality in unintended ways — for example, using DNS zone transfers to enumerate internal infrastructure, abusing MQTT''s publish/subscribe model to access sensitive system topics, or issuing Redis commands like SLAVEOF or CONFIG to achieve remote code execution on exposed instances.
INSERT INTO attack_definitions VALUES ('RCE', 'Remote Code Execution (RCE)', 'Remote Code Execution (RCE) is a class of vulnerability that allows an attacker to run arbitrary commands or code on a target system from a remote location, typically without requiring prior authentication or physical access. It represents one of the most severe and impactful vulnerability classes in cybersecurity.', 'web', 'Remote Code Execution (RCE) refers to a category of security vulnerabilities that permit an adversary to execute arbitrary instructions on a victim''s machine, server, or networked device from across a network — often the internet — without legitimate authorization. RCE vulnerabilities can manifest in virtually any software layer: web applications, operating system services, network daemons, deserialization routines, template engines, and more. When successfully exploited, the attacker gains the ability to operate within the context of the compromised process, which may run with elevated (sometimes SYSTEM or root) privileges.
INSERT INTO attack_definitions VALUES ('RFI', 'Remote File Inclusion (RFI)', 'Remote File Inclusion is a web application vulnerability that allows an attacker to include and execute a remotely hosted malicious file via a vulnerable parameter, typically leading to arbitrary code execution on the target server.', 'web', 'Remote File Inclusion (RFI) is a class of injection vulnerability affecting web applications that dynamically include files based on user-supplied input without adequate validation or sanitization. When a PHP, ASP, or other server-side application constructs a file path using parameters such as `include($_GET[''page''])`, an attacker can substitute a legitimate path with a URL pointing to a remotely hosted malicious script, causing the server to fetch and execute attacker-controlled code.
INSERT INTO attack_definitions VALUES ('SCANNER', 'Internet-Wide Scanner / Automated Reconnaissance Tool', 'Automated scanning engines operated by security research organizations, threat intelligence platforms, and adversaries that systematically probe internet-connected assets to enumerate open ports, services, banners, and vulnerabilities at scale.', 'recon', 'Internet-wide scanners are automated systems that continuously or periodically probe every routable IPv4 (and increasingly IPv6) address across the public internet, collecting information about open ports, running services, software versions, TLS certificates, and exposed interfaces. Well-known commercial and academic scanners include Shodan, Censys, ZoomEye, BinaryEdge, Shadowserver, and Rapid7''s Project Sonar. These platforms maintain persistent, searchable databases of internet-facing assets and are used legitimately for vulnerability research, asset inventory, and threat intelligence. However, the same scan data is routinely weaponized by threat actors to identify vulnerable or misconfigured targets without ever generating noise on the target network until exploitation begins.
INSERT INTO attack_definitions VALUES ('SHELLSHOCK', 'Shellshock (Bash Remote Code Execution)', 'Shellshock is a critical vulnerability in the GNU Bash shell (CVE-2014-6271 and related CVEs) that allows attackers to inject and execute arbitrary operating system commands by embedding malicious function definitions in environment variables processed by Bash.', 'web', 'Shellshock refers to a family of security bugs discovered in September 2014 affecting the GNU Bourne Again Shell (Bash), versions through 4.3. The core vulnerability lies in how Bash processes function definitions stored in environment variables. When Bash initializes, it imports functions defined in environment variables by parsing strings of the form ''() { ... };''. The flaw is that Bash continued parsing and executing any commands appended after the closing brace of the function definition, allowing arbitrary code execution during shell initialization.
INSERT INTO attack_definitions VALUES ('SMB', 'Server Message Block (SMB) Protocol Attacks', 'SMB protocol attacks exploit Microsoft''s file-sharing protocol to achieve lateral movement, credential theft, remote code execution, and ransomware propagation across Windows networks. Attackers leverage misconfigurations, stolen credentials, and vulnerabilities in SMB implementations to move through enterprise environments and exfiltrate data.', 'network', 'Server Message Block (SMB) is a network communication protocol used primarily on Windows systems for sharing files, printers, and other resources across a network. Originally developed by IBM and later extended by Microsoft, SMB operates over TCP port 445 (and legacy NetBIOS ports 137-139). Due to its deep integration into Windows environments and widespread deployment, SMB has become one of the most targeted protocols by threat actors ranging from nation-state APTs to ransomware operators.
INSERT INTO attack_definitions VALUES ('SMB_EXPLOIT_PROBE', 'SMB Exploit Probe / EternalBlue-Style SMB Exploitation Attempt', 'An attacker probes or exploits vulnerabilities in the Server Message Block (SMB) protocol, particularly targeting legacy SMBv1 Trans2 request handling to achieve remote code execution, lateral movement, or worm-like propagation across networks.', 'network', 'SMB (Server Message Block) exploit probes represent a class of network-layer attacks targeting weaknesses in Microsoft''s file and printer sharing protocol, most notably SMBv1. The SMB protocol operates over TCP port 445 (and legacy NetBIOS ports 137-139) and is ubiquitous in Windows enterprise environments. Attackers scan for and exploit buffer overflows, type confusion errors, and improper input validation within SMB request handlers to gain unauthenticated remote code execution with SYSTEM-level privileges.
INSERT INTO attack_definitions VALUES ('SMB_SCAN', 'SMB Network Scanning and Enumeration', 'SMB scanning is a reconnaissance technique where attackers probe networks for hosts running the Server Message Block (SMB) protocol, typically on TCP ports 139 and 445, to identify vulnerable systems, enumerate shares, users, and services prior to exploitation.', 'recon', 'Server Message Block (SMB) scanning is a foundational reconnaissance activity performed by threat actors, penetration testers, and automated malware to map network infrastructure and identify attack surfaces. SMB operates on TCP port 445 (direct SMB over TCP) and TCP port 139 (SMB over NetBIOS), and has historically been a highly targeted protocol due to its prevalence in Windows environments and its history of critical vulnerabilities including EternalBlue (MS17-010), WannaCry, and NotPetya.
INSERT INTO attack_definitions VALUES ('SMTP_PROBE', 'SMTP Probe / Email Server Reconnaissance', 'SMTP probing is a reconnaissance technique where attackers abuse standard SMTP commands such as VRFY, EXPN, RCPT TO, and EHLO to enumerate valid email addresses, discover mail server configurations, and map internal infrastructure without sending actual email.', 'recon', 'SMTP probing exploits the inherent verbosity of the Simple Mail Transfer Protocol (SMTP), defined in RFC 5321, to extract information about an organization''s mail infrastructure. Attackers leverage commands originally designed for server administration and mail routing to enumerate valid user accounts, discover mailing lists, fingerprint mail server software, and identify relay capabilities — all without delivering a single email message.
INSERT INTO attack_definitions VALUES ('SQLI', 'SQL Injection (SQLI)', 'SQL Injection is an attack technique where malicious SQL code is inserted into application input fields to manipulate backend database queries, enabling unauthorized data access, modification, or destruction.', 'web', 'SQL Injection (SQLI) is one of the oldest and most pervasive web application vulnerabilities, consistently ranking in the OWASP Top 10. It occurs when user-supplied input is incorporated into SQL queries without adequate sanitization or parameterization, allowing an attacker to alter the query''s logic. The attack exploits the trust relationship between the application layer and the database layer, treating attacker-controlled data as executable SQL code.
INSERT INTO attack_definitions VALUES ('SSRF', 'Server-Side Request Forgery (SSRF)', 'SSRF is a web vulnerability that allows attackers to induce the server-side application to make HTTP requests to an arbitrary domain or internal resource of the attacker''s choosing. This can be used to pivot into internal networks, access cloud metadata services, or interact with internal services not exposed to the internet.', 'web', 'Server-Side Request Forgery (SSRF) occurs when a web application fetches a remote resource based on user-supplied input without adequate validation or sanitization. The server, trusted by internal infrastructure, acts as a proxy for the attacker''s requests, reaching destinations that are otherwise inaccessible from the public internet. Because the request originates from the server itself, firewall rules and network segmentation controls that would block external clients are often bypassed entirely.
INSERT INTO attack_definitions VALUES ('SUPPLY_CHAIN', 'Software Supply Chain Attack', 'Software supply chain attacks compromise the integrity of software dependencies, build pipelines, or distribution mechanisms to inject malicious code into downstream targets. Attackers exploit the trust developers place in third-party packages, registries, and tooling to achieve widespread, stealthy compromise.', 'supply_chain', 'Software supply chain attacks target the ecosystem of tools, libraries, and services that developers rely upon to build and deploy software. Rather than attacking a hardened production system directly, adversaries infiltrate the upstream components — package registries (npm, PyPI, RubyGems), version control systems, CI/CD pipelines, or update mechanisms — so that malicious code is delivered automatically to any organisation consuming the compromised component. This makes supply chain attacks uniquely dangerous: a single compromised package can propagate to tens of thousands of organisations simultaneously.
INSERT INTO attack_definitions VALUES ('XXE', 'XML External Entity Injection (XXE)', 'XXE is a web security vulnerability that exploits insecure XML parsers to process external entity references, allowing attackers to read arbitrary files, perform server-side request forgery, or execute denial-of-service attacks.', 'web', 'XML External Entity (XXE) injection is a class of attack targeting applications that parse XML input. The XML specification allows documents to define ''entities'' — reusable pieces of content — including ''external entities'' that reference resources outside the document itself, such as local files or remote URLs. When an XML parser is configured to process these external entity declarations, an attacker can craft malicious XML payloads to cause the server to retrieve and expose sensitive data.
INSERT INTO attack_definitions VALUES ('FORTI_ATTACK', 'Fortinet Device Exploitation (FORTI_ATTACK)', 'Exploitation of critical vulnerabilities in Fortinet network security products including FortiOS, FortiProxy, and FortiGate appliances, targeting authentication bypass, remote code execution, and configuration disclosure flaws.', 'network', 'Fortinet device attacks represent a class of high-impact exploitation campaigns targeting widely deployed network security infrastructure including FortiGate firewalls, FortiProxy SSL-VPN gateways, and FortiOS management interfaces. These attacks leverage critical CVEs that have been actively weaponized by nation-state actors, ransomware operators, and cybercriminal groups due to the privileged network position these devices occupy. Successful compromise of a perimeter security device provides attackers with near-complete network visibility and lateral movement opportunities.
INSERT INTO attack_definitions VALUES ('SSTI', 'Server-Side Template Injection (SSTI)', 'Server-Side Template Injection occurs when user-supplied input is embedded unsafely into a server-side template engine, allowing attackers to inject and execute arbitrary template directives that can lead to remote code execution.', 'web', 'Server-Side Template Injection (SSTI) is a class of injection vulnerability that arises when web applications dynamically render content by embedding untrusted user input directly into template strings processed by a server-side template engine such as Jinja2, Twig, FreeMarker, Velocity, Smarty, or Pebble. Unlike client-side template injection, SSTI executes within the server process, granting the attacker access to the full power of the template engine''s expression language and, in many cases, the underlying operating system.
INSERT INTO attack_definitions VALUES ('XSS', 'Cross-Site Scripting (XSS)', 'Cross-Site Scripting (XSS) is a client-side code injection vulnerability where attackers inject malicious scripts into web pages viewed by other users, enabling session hijacking, credential theft, and malware delivery.', 'web', 'Cross-Site Scripting (XSS) is one of the most prevalent and long-standing vulnerabilities in web application security. It occurs when an application incorporates untrusted data into a web page without proper validation or encoding, allowing attackers to inject and execute arbitrary JavaScript or other client-side code within a victim''s browser context. Because the malicious script executes within the trusted origin of the vulnerable site, the browser has no inherent mechanism to distinguish it from legitimate page content.
INSERT INTO attack_definitions VALUES ('ICS_ATTACK', 'Industrial Control System (ICS) / SCADA Attack via DNP3 Protocol', 'Attacks targeting Industrial Control Systems using the DNP3 (Distributed Network Protocol 3) protocol to manipulate, disrupt, or surveil operational technology (OT) devices such as RTUs, PLCs, and IEDs in critical infrastructure environments.', 'ics', 'Industrial Control System (ICS) attacks via DNP3 represent a class of highly targeted cyber-physical threats aimed at operational technology environments in sectors such as electric utilities, water treatment, oil and gas, and transportation. DNP3 (IEEE Std 1815) is a SCADA communication protocol originally designed for reliability over noisy communication channels, not for security, and it lacks native authentication and encryption in many legacy deployments. Attackers who gain access to ICS networks can issue legitimate-looking DNP3 commands to manipulate field devices, disrupt operations, or gather intelligence on physical processes.
INSERT INTO attack_definitions VALUES ('LOG4SHELL', 'Log4Shell (Apache Log4j JNDI Injection)', 'Log4Shell is a critical remote code execution vulnerability in Apache Log4j 2 that allows unauthenticated attackers to execute arbitrary code by injecting malicious JNDI lookup strings into any log-processed input field. Exploitation requires no authentication and affects an enormous swath of Java-based applications worldwide.', 'web', 'Log4Shell (CVE-2021-44228) is a zero-day vulnerability discovered in November 2021 in the Apache Log4j 2 logging library, one of the most widely used Java logging frameworks. The vulnerability exists in Log4j''s message lookup substitution feature, which processes special syntax such as ${jndi:ldap://...} embedded in log messages. When an application logs attacker-controlled input — including HTTP headers, form fields, usernames, or User-Agent strings — the logging library automatically resolves the embedded JNDI expression, reaching out to an attacker-controlled server.
INSERT INTO attack_cve_links VALUES (1, 'AI_ATTACK', 'CVE-2024-5184', 'EmailGPT Prompt Injection', NULL, 'EmailGPT', NULL, NULL, NULL, NULL, 'Prompt injection vulnerability in EmailGPT allowing attackers to exfiltrate data and override system instructions via crafted email content processed by the LLM.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (2, 'AI_ATTACK', 'CVE-2023-32786', 'LangChain Prompt Injection', NULL, 'LangChain', NULL, NULL, NULL, NULL, 'Improper handling of untrusted input in LangChain''s LLMChain allowed prompt injection leading to arbitrary code execution via agent tool calls.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (3, 'AI_ATTACK', 'CVE-2023-36188', 'LangChain SSRF via Prompt Injection', NULL, 'LangChain', NULL, NULL, NULL, NULL, 'Prompt injection in LangChain enabled SSRF attacks by manipulating agent-issued HTTP requests to internal network resources.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (4, 'AI_ATTACK', 'CVE-2024-27564', 'ChatGPT Plugin Prompt Injection', NULL, 'OpenAI ChatGPT Plugins', NULL, NULL, NULL, NULL, 'Indirect prompt injection via malicious web content retrieved by ChatGPT browsing plugin, allowing attacker-controlled instructions to influence model behaviour.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (5, 'AI_ATTACK', 'CVE-2024-34359', 'Llama CPP Python Injection', NULL, 'llama-cpp-python', NULL, NULL, NULL, NULL, 'Improper input handling in llama-cpp-python server allowed remote code execution through crafted prompt payloads targeting the model server API.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (6, 'API_ABUSE', 'CVE-2022-21449', 'Psychic Signatures', NULL, 'Oracle Java SE / JDK', NULL, NULL, NULL, NULL, 'ECDSA signature validation bypass in Java allowing blank/zero-value signatures to be accepted as valid, enabling JWT and other signed-token forgery without knowledge of the private key.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (7, 'API_ABUSE', 'CVE-2015-9235', 'JWT None Algorithm Vulnerability', NULL, 'node-jsonwebtoken (npm)', NULL, NULL, NULL, NULL, 'The jsonwebtoken library accepted tokens with alg:none and no signature, allowing complete authentication bypass in any application using the affected version.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (8, 'API_ABUSE', 'CVE-2016-10555', 'JWT Algorithm Confusion', NULL, 'jwt-simple (npm)', NULL, NULL, NULL, NULL, 'jwt-simple did not validate the algorithm field in JWT headers, enabling algorithm confusion attacks where RS256 tokens could be forged using HS256 with the public key as the secret.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (9, 'API_ABUSE', 'CVE-2020-28042', 'JWT KID SQL Injection', NULL, 'PyJWT / python-jwt', NULL, NULL, NULL, NULL, 'Multiple Python JWT libraries passed the kid header field unsanitized to key lookup functions, enabling SQL injection and path traversal to manipulate the signing key used for verification.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (10, 'API_ABUSE', 'CVE-2022-39227', 'python-jwt Claims Forgery', NULL, 'python-jwt', NULL, NULL, NULL, NULL, 'A vulnerability in python-jwt allowed attackers to inject crafted claims into existing valid tokens without invalidating the signature, enabling privilege escalation by inserting arbitrary claims.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (11, 'AUTH_ATTACK', 'CVE-2022-22965', 'Spring4Shell', NULL, 'Spring Framework', NULL, NULL, NULL, NULL, 'Remote code execution vulnerability in Spring MVC that could be chained with authentication bypass to achieve full system compromise.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (12, 'AUTH_ATTACK', 'CVE-2021-40539', 'Zoho ManageEngine ADSelfService Plus Auth Bypass', NULL, 'Zoho ManageEngine ADSelfService Plus', NULL, NULL, NULL, NULL, 'Authentication bypass vulnerability in self-service password reset portal allowing unauthenticated remote code execution, exploited by APT27.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (13, 'AUTH_ATTACK', 'CVE-2020-14882', 'Oracle WebLogic Console Auth Bypass', NULL, 'Oracle WebLogic Server', NULL, NULL, NULL, NULL, 'Authentication bypass in Oracle WebLogic Console allowing unauthenticated access to the administrative interface via URL manipulation.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (14, 'AUTH_ATTACK', 'CVE-2019-11043', 'PHP-FPM Remote Code Execution', NULL, 'PHP-FPM with Nginx', NULL, NULL, NULL, NULL, 'Vulnerability enabling authentication bypass and code execution through malformed URL paths in specific PHP-FPM/Nginx configurations.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (15, 'AUTH_ATTACK', 'CVE-2018-1000531', 'InVision Password Reset Host Header Injection', NULL, 'InVision', NULL, NULL, NULL, NULL, 'Password reset host header injection vulnerability allowing attackers to hijack password reset tokens by manipulating the HTTP Host header.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
INSERT INTO attack_cve_links VALUES (16, 'CLOUD_ATTACK', 'CVE-2021-21315', 'systeminformation SSRF', NULL, 'systeminformation npm package', NULL, NULL, NULL, NULL, 'SSRF vulnerability in systeminformation npm package allowed attackers to reach IMDS endpoints from Node.js applications running on cloud instances.', NULL, NULL, false, NULL, false, false, NULL, 'primary', NULL);
