INSERT INTO attack_definitions (attack_type, display_name, short_description, category, full_description, how_it_works, impact, prerequisites, detection_methods, prevention) VALUES ('REDIS_MEMORY_CORRUPTION', 'Redis Memory-Corruption RCE (redis-poc)', 'Authenticated memory-corruption RCEs against modern Redis: a stream consumer-group NACK double-free (CVE-2026-25243) reached via RESTORE + XGROUP, and RedisBloom TopK wild-free / TDigest heap overflow (CVE-2026-25589) via crafted TOPK.* / TDIGEST.* parameters.', 'network', 'The berabuddies/redis-poc exploits target heap-management bugs in Redis 6.2.22 / 7.4.9 / 8.6.4 and the bundled RedisBloom module (8.8.x). They require valid authentication and abuse legitimate commands to corrupt heap metadata rather than any single command-level RCE like SLAVEOF or MODULE LOAD.', 'CVE-2026-25243: the attacker RESTOREs a crafted serialized stream object, then drives the consumer-group NACK path (XGROUP CREATE, XREADGROUP, XACK/XCLAIM, XGROUP DELCONSUMER) so a shared NACK is freed twice, yielding a controllable double-free. CVE-2026-25589: crafted TOPK.RESERVE / TDIGEST.CREATE parameters (negative or implausibly large widths/compression) trigger a wild free / heap overflow inside RedisBloom.', 'Remote code execution in the redis-server process (often the redis service account), enabling host compromise, lateral movement, and data theft.', 'Network access to the Redis port and valid credentials (or an unauthenticated instance). For the RedisBloom paths, the bundled module must be loaded.', 'HoneyLens captures the RESTORE serialized blob, the stream consumer-group sequence, and anomalous TOPK./TDIGEST. parameters, emitting REDIS_HEAP_CORRUPT / REDIS_TOPK_WILDFREE / REDIS_TDIGEST_OVERFLOW and a correlated REDIS_EXPLOIT_CHAIN event. Suricata SIDs 9026720-9026726 match the RESP patterns on the wire.', 'Patch Redis and RedisBloom to fixed versions, require strong authentication, bind Redis to trusted interfaces only, disable unused modules, and run redis-server as an unprivileged, sandboxed account.');
INSERT INTO attack_definitions (attack_type, display_name, short_description, category, full_description, how_it_works, impact, prerequisites, detection_methods, prevention) VALUES ('AI_AGENT_CALLBACK', 'AI Agent Canary Callback (prompt-injection canary)', 'An automated AI agent read honeypot output and obeyed a benign instruction planted inside it, revealing that the attacker''s pipeline feeds unvetted honeypot content to a language model.', 'recon', 'HoneyLens plants a harmless instruction in credential-like honeypot responses — a Kubernetes Secret or kubeconfig, an issued PAN-OS API key, a granted FortiGate admin session, an nginx CVE response, an LLM chat completion. The instruction asks an autonomous AI agent to fetch a unique URL and explicitly tells it not to send any credential material. A human reading the same response has no reason to act on it, so a callback is strong evidence that the response was processed by an agent rather than a person.', 'Each issued canary carries a random nonce recorded in the ai_prompt_canaries registry together with what was read and which address read it. When the callback arrives on the honeypot port, the sensor correlates it back to that artefact — including across honeypots, since the canary may have been issued by one process and answered by another. The callback carries no secret: the finding is the fact of the request, its latency, its user-agent, and above all whether the answering address differs from the address that harvested the credential.', 'None to the sensor — no code runs and no data is exfiltrated. The value is intelligence: it exposes AI-assisted automation in the attacker pipeline, links otherwise unrelated source addresses belonging to the same operator, and reveals that honeypot output is being ingested by a model that follows instructions it finds in untrusted data.', 'The canary must be enabled (AI_CANARY_ENABLED, off by default) and the callback URL reachable from the agent. Rate-limited per source and host-validated so the sensor cannot be used to bounce traffic at third parties.', 'The honeypot serving the callback path emits an AI_AGENT_CALLBACK event (severity high) and the ingest correlates it with the issuing artefact. Suricata SIDs 9026740-9026742 match the callback on the wire, including agents that POST a body despite being told not to send data, and the case where the instruction is replayed back at the sensor. Any source with such an event is tagged AI_ASSISTED_AUTOMATION.', 'For defenders running AI-assisted triage: treat scanner and honeypot output as untrusted input, never feed it to a model with network or tool access, strip or neutralise instruction-like text before summarisation, and require human approval for any action a model proposes from harvested content.');
INSERT INTO attack_definitions (attack_type, display_name, short_description, category, full_description, how_it_works, impact, prerequisites, detection_methods, prevention) VALUES ('WAGO_CONTROL_WRITE', 'WAGO Controller Process/State Write', 'An attacker changed what a PLC is doing — a pump, a valve, a setpoint, or the controller run state — through the WAGO Web-Based Management or WebVisu interface.', 'ics', 'WAGO PFC100/PFC200 controllers expose a Web-Based Management (WBM) interface and an optional WebVisu process view. Both can write: WBM administration can put the CODESYS runtime into RUN, STOP or RESET, and WebVisu forms write directly into the process image (coils and holding registers). On an internet-exposed controller these are reachable over plain HTTP.', 'The attacker POSTs to the WBM administration page with plc-action=stop or reset, or to the WebVisu handler with process fields (pump, setpoint, valve). No exploit is required — this is the device''s own management surface used as designed, by someone who should not have it. The dangerous sequence is reconnaissance first: read /wbm/io_config.xml to learn which modules and channels exist, then write to the ones that matter.', 'On a real plant this is physical: a stopped controller halts a process, a changed setpoint or valve position moves it to a state nobody chose. Stopping the CODESYS runtime is a denial of service against the process itself, not just a network service.', 'Network reachability to the controller''s WBM port. Authentication is often absent, weak, or bypassable (see CVE-2023-1698).', 'The HoneyLens WAGO honeypot classifies WBM and WebVisu writes as WAGO_CONTROL_WRITE (critical) and correlates an I/O-map read followed by a process write from the same source as recon_then_control. Suricata SIDs 9026750-9026759 cover the same shapes on the wire, including PLC stop/reset (9026752) and WebVisu process writes (9026753).', 'Never expose controller management to the internet — put it behind a VPN or a jump host on a segmented OT network. Change vendor default credentials, keep firmware current (CVE-2023-1698 allows unauthenticated user creation and configuration change, CVSS 9.8), disable unused services on the controller, and alert on any write to the process image from outside the engineering workstation.');
INSERT INTO attack_definitions (attack_type, display_name, short_description, category, full_description, how_it_works, impact, prerequisites, detection_methods, prevention) VALUES ('VPN_RECON', 'SSL-VPN Tunnel-Group Enumeration (Cisco AnyConnect / ASA)', 'An unsolicited AnyConnect client handshake against an SSL-VPN gateway, used to discover which tunnel-group (connection profile) names exist before credentials are attempted against the one that answers.', 'recon', 'Cisco ASA and Secure Firewall gateways present SSL-VPN access through named connection profiles, historically called tunnel-groups. A client announces which profile it wants in the aggregate-auth handshake, and the gateway answers differently for a profile that exists than for one that does not. That difference is an oracle: an attacker who can enumerate valid profile names learns which authentication backend to attack, which group policies are in play, and often something about the organisation itself, because profile names are rarely generic. Nothing here abuses a vulnerability — the handshake is the protocol working as designed, which is exactly why it does not appear in any CVE and why volume-based detection matters more than signature matching.', 'The client POSTs an XML `<config-auth client="vpn" type="init">` document to the gateway root over TLS. It contains a `<group-select>` naming the profile being tried, a `<device-id>` reporting the endpoint hardware and OS, the client version, and the endpoint MAC address. A gateway that recognises the profile returns its authentication form; one that does not returns an error or falls back to the default group. Enumeration tools iterate profile names across many source addresses to stay under per-IP rate limits — the campaign observed by HoneyLens used 648 distinct source IPs for a single profile name, spreading the load rather than the wordlist.', 'No direct compromise. This is the step that decides where a credential attack is aimed, so it is valuable as early warning: enumeration against a real gateway usually precedes password spraying against the profile that responded. On a honeypot the value is inverted — the handshake reveals the tooling, because a generated client cannot help but describe itself in the device report it sends.', 'The gateway must be reachable and speaking the AnyConnect aggregate-auth protocol. No credentials and no authentication are required; enumeration happens entirely before the login step.', 'Suricata SIDs 9026760-9026763. The traffic is TLS, so the request body is not visible on the wire and SID 9026760 matches the client JA3 fingerprint instead — on HoneyLens sensors that fingerprint covered 99.7% of the sources that were independently confirmed by their request bodies, and reached 648 sources where bodies identified 364. The remaining SIDs match the cleartext case: the config-auth handshake, an end-of-life 3.x/4.x AnyConnect user-agent, and a client reporting a MAC address with the multicast bit set — an address no physical NIC can carry, which appears in roughly half of a generated client population because tools rarely mask that bit. Honeypot-side, the classifier tags the same traffic VPN_RECON from the captured body.', 'Do not expose the SSL-VPN portal to the whole internet where a geographic or allowlist restriction is workable. Name connection profiles so a valid name is not guessable and does not disclose the organisation. Ensure the gateway answers identically for valid and invalid profiles where the platform allows it, so the oracle closes. Rate-limit and alert on handshake volume per source and in aggregate — a distributed enumeration is invisible per-IP and obvious in total. Keep the gateway patched and retire AnyConnect 4.x clients, so a 4.x user-agent becomes unambiguous rather than merely suspicious.');
